const fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto'),assert=require('node:assert/strict'),path=require('node:path');const hash=b=>crypto.createHash('sha256').update(b).digest('hex');const m=JSON.parse(fs.readFileSync('docs/plan/c2-wecom/MANIFEST.json','utf8'));for(const r of m.files){const w=fs.readFileSync(r.path),b=cp.execFileSync('git',['show',':'+r.path],{maxBuffer:12000000});assert.equal(w.length,r.worktree.bytes);assert.equal(hash(w),r.worktree.sha256);assert.equal(b.length,r.gitBlob.bytes);assert.equal(hash(b),r.gitBlob.sha256)}let links=0;for(const r of m.files.filter(x=>x.path.endsWith('.md'))){const s=fs.readFileSync(r.path,'utf8');for(const x of s.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){const href=x[1];if(/^[a-z]+:|^#|^\//i.test(href))continue;const target=path.resolve(path.dirname(r.path),href.split('#')[0]);assert(fs.existsSync(target),'broken link '+r.path+' -> '+href);links++}}console.log(JSON.stringify({manifestFiles:m.files.length,manifestMismatches:0,localMarkdownLinksChecked:links,productSourceChanges:0}));
